mapper.select:
SELECT id, aggregator_id, ent_id, start_date, end_date, apply_time, plan_status
FROM aggregator_ent_apply_plan
WHERE ent_id = #{entId}
AND save_status = #{saveStatus}
ORDER BY plan_status ASC, apply_time DESC

SELECT id, aggregator_id, ent_id, start_date, end_date, apply_time, plan_status
FROM aggregator_ent_apply_plan
WHERE ent_id = #{entId}
AND plan_status = #{planStatus}
AND save_status = true
ORDER BY apply_time DESC

SELECT id, aggregator_id, ent_id, start_date, end_date, apply_time, plan_status, IF(start_date <= #{date} AND end_date >= #{date} ,0,1) AS dataStatus
FROM aggregator_ent_apply_plan
WHERE ent_id = #{entId}
AND plan_status = #{planStatus}
ORDER BY dataStatus, apply_time DESC

SELECT id, aggregator_id, ent_id, start_date, end_date, apply_time, plan_status
FROM aggregator_ent_apply_plan
WHERE ent_id = #{entId}
AND end_date < #{endDate}
AND plan_status = #{planStatus}
AND save_status = true
ORDER BY apply_time DESC

SELECT id, aggregator_id, ent_id, start_date, end_date, apply_time, plan_status
FROM aggregator_ent_apply_plan
WHERE ent_id = #{entId}
AND start_date <= #{date}
AND end_date >= #{date}
AND plan_status = #{planStatus}
AND save_status = true
ORDER BY apply_time DESC

SELECT id, aggregator_id, ent_id, start_date, end_date, apply_time, plan_status
FROM aggregator_ent_apply_plan
WHERE ent_id = #{entId}
AND start_date <= #{date}
AND end_date >= #{date}
AND plan_status = #{planStatus}
AND save_status = true
ORDER BY apply_time DESC
LIMIT 1

SELECT id, aggregator_id, ent_id, start_date, end_date, apply_time, plan_status
FROM aggregator_ent_apply_plan
WHERE ent_id = #{entId}
AND start_date > #{startDate}
AND plan_status = #{planStatus}
AND save_status = true
UNION
(SELECT id, aggregator_id, ent_id, start_date, end_date, apply_time, plan_status
FROM aggregator_ent_apply_plan
WHERE ent_id = #{entId}
AND start_date <= #{startDate}
AND end_date >= #{startDate}
AND plan_status = #{planStatus}
AND save_status = true
AND id <>
(SELECT id FROM aggregator_ent_apply_plan
WHERE ent_id = #{entId}
AND start_date <= #{startDate}
AND end_date >= #{startDate}
AND plan_status = #{planStatus}
AND save_status = true
ORDER BY apply_time DESC LIMIT 1)
)
ORDER BY apply_time DESC
